import 'dart:async';import 'dart:math';import 'package:flutter/services.dart';import 'package:sensors_plus/sensors_plus.dart';import '../data/location_safety_service.dart';class PanicButtonService {  final LocationSafetyService _safetyService;  StreamSubscription? _accelerometerSub;  int _shakeCount = 0;  DateTime? _lastShakeTime;  Timer? _shakeResetTimer;  static const double _shakeThreshold = 25.0;  static const int _requiredShakes = 3;  static const Duration _shakeWindow = Duration(seconds: 2);  static const Duration _shakeCooldown = Duration(seconds: 5);  final _panicTriggered = StreamController<void>.broadcast();  Stream<void> get onPanicTriggered => _panicTriggered.stream;  PanicButtonService(this._safetyService);  void startListening() {    _accelerometerSub = accelerometerEventStream().listen(_onAccelerometerData);  }  void _onAccelerometerData(AccelerometerEvent event) {    final magnitude =        sqrt(event.x * event.x + event.y * event.y + event.z * event.z);    if (magnitude > _shakeThreshold) {      _handleShakeDetected();    }  }  void _handleShakeDetected() {    final now = DateTime.now();    if (_lastShakeTime != null &&        now.difference(_lastShakeTime!) > _shakeCooldown) {      _shakeCount = 0;    }    if (_lastShakeTime == null ||        now.difference(_lastShakeTime!) < _shakeWindow) {      _shakeCount++;      _lastShakeTime = now;      _shakeResetTimer?.cancel();      _shakeResetTimer = Timer(_shakeWindow, () {        _shakeCount = 0;      });      if (_shakeCount >= _requiredShakes) {        _triggerPanic();        _shakeCount = 0;      }    } else {      _shakeCount = 1;      _lastShakeTime = now;    }  }  void _triggerPanic() {    HapticFeedback.heavyImpact();    HapticFeedback.vibrate();    _panicTriggered.add(null);  }  void stopListening() {    _accelerometerSub?.cancel();    _shakeResetTimer?.cancel();  }  void dispose() {    stopListening();    _panicTriggered.close();  }}